#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <memory>
#include <cstring>
#include <zlib.h>
#include <sys/stat.h>
#include <filesystem>

namespace fs = std::filesystem;

struct ContainerManifest {
    std::string image_name;
    std::string tag;
    std::vector<std::string> layers;
    size_t total_size;
};

class DecompressionPolicy {
public:
    static constexpr size_t MAX_COMPRESSED_SIZE = 100 * 1024 * 1024;  // 100MB
    static constexpr size_t MAX_DECOMPRESSED_SIZE = 1ULL * 1024 * 1024 * 1024;  // 1GB
    static constexpr double MAX_COMPRESSION_RATIO = 100.0;
    static constexpr size_t CHUNK_SIZE = 16384;

    bool validate_compressed_size(size_t size) const {
        return size <= MAX_COMPRESSED_SIZE;
    }

    bool validate_ratio(size_t compressed, size_t decompressed) const {
        if (compressed == 0) return false;
        double ratio = static_cast<double>(decompressed) / static_cast<double>(compressed);
        return ratio <= MAX_COMPRESSION_RATIO;
    }

    bool validate_output_size(size_t current_output) const {
        return current_output <= MAX_DECOMPRESSED_SIZE;
    }
};

class LayerExtractor {
private:
    DecompressionPolicy policy_;
    std::string workspace_;
    size_t total_bytes_written_;

    struct StreamState {
        z_stream strm;
        bool initialized;
        size_t bytes_in;
        size_t bytes_out;
    };

public:
    LayerExtractor(const std::string& workspace)
        : workspace_(workspace), total_bytes_written_(0) {
        fs::create_directories(workspace_);
    }

    int extract_layer(const std::string& layer_path, const std::string& output_dir) {
        struct stat st;
        if (stat(layer_path.c_str(), &st) != 0) {
            return -1;
        }

        size_t compressed_size = static_cast<size_t>(st.st_size);
        if (!policy_.validate_compressed_size(compressed_size)) {
            std::cerr << "Layer exceeds maximum compressed size" << std::endl;
            return -1;
        }

        return decompress_stream(layer_path, output_dir, compressed_size);
    }

private:
    int decompress_stream(const std::string& input_path,
                          const std::string& output_dir,
                          size_t compressed_size) {
        StreamState state{};
        state.initialized = false;
        state.bytes_in = 0;
        state.bytes_out = 0;

        memset(&state.strm, 0, sizeof(z_stream));
        int ret = inflateInit2(&state.strm, 15 + 32);  // gzip + zlib
        if (ret != Z_OK) return -1;
        state.initialized = true;

        std::ifstream infile(input_path, std::ios::binary);
        if (!infile.is_open()) {
            inflateEnd(&state.strm);
            return -1;
        }

        std::string output_path = output_dir + "/layer.tar";
        std::ofstream outfile(output_path, std::ios::binary);
        if (!outfile.is_open()) {
            inflateEnd(&state.strm);
            return -1;
        }

        std::vector<unsigned char> in_buf(DecompressionPolicy::CHUNK_SIZE);
        std::vector<unsigned char> out_buf(DecompressionPolicy::CHUNK_SIZE);

        size_t layer_bytes_out = 0;
        bool ratio_checked = false;

        do {
            infile.read(reinterpret_cast<char*>(in_buf.data()), in_buf.size());
            state.strm.avail_in = static_cast<uInt>(infile.gcount());
            if (state.strm.avail_in == 0) break;

            state.bytes_in += state.strm.avail_in;
            state.strm.next_in = in_buf.data();

            do {
                state.strm.avail_out = static_cast<uInt>(out_buf.size());
                state.strm.next_out = out_buf.data();

                ret = inflate(&state.strm, Z_NO_FLUSH);
                if (ret == Z_STREAM_ERROR || ret == Z_DATA_ERROR ||
                    ret == Z_MEM_ERROR) {
                    inflateEnd(&state.strm);
                    return -1;
                }

                size_t have = DecompressionPolicy::CHUNK_SIZE - state.strm.avail_out;
                layer_bytes_out += have;
                state.bytes_out += have;
                total_bytes_written_ += have;

                // Check decompressed size limit
                if (!policy_.validate_output_size(total_bytes_written_)) {
                    std::cerr << "Total decompressed output exceeds limit" << std::endl;
                    inflateEnd(&state.strm);
                    return -1;
                }

                // Ratio check after first meaningful data
                if (!ratio_checked && state.bytes_in >= DecompressionPolicy::CHUNK_SIZE) {
                    ratio_checked = true;
                    if (!policy_.validate_ratio(state.bytes_in, state.bytes_out)) {
                        std::cerr << "Compression ratio exceeds policy" << std::endl;
                        inflateEnd(&state.strm);
                        return -1;
                    }
                }

                outfile.write(reinterpret_cast<char*>(out_buf.data()), have);
            } while (state.strm.avail_out == 0);

        } while (ret != Z_STREAM_END);

        inflateEnd(&state.strm);
        return 0;
    }
};

class ContainerOrchestrator {
private:
    std::string staging_dir_;
    std::unique_ptr<LayerExtractor> extractor_;

public:
    ContainerOrchestrator(const std::string& staging)
        : staging_dir_(staging) {
        extractor_ = std::make_unique<LayerExtractor>(staging + "/work");
    }

    int process_upload(const std::string& upload_path) {
        auto manifest = parse_manifest(upload_path);
        if (!manifest) return -1;

        for (size_t i = 0; i < manifest->layers.size(); ++i) {
            std::string layer_file = staging_dir_ + "/layers/" + manifest->layers[i];
            std::string layer_output = staging_dir_ + "/extracted/layer_" + std::to_string(i);
            fs::create_directories(layer_output);

            // Each layer gets its own extractor to isolate byte counting
            LayerExtractor layer_extractor(layer_output);
            int result = layer_extractor.extract_layer(layer_file, layer_output);
            if (result != 0) {
                std::cerr << "Failed to extract layer " << i << std::endl;
                return -1;
            }
        }
        return 0;
    }

private:
    std::unique_ptr<ContainerManifest> parse_manifest(const std::string& path) {
        auto manifest = std::make_unique<ContainerManifest>();
        std::ifstream mf(path + "/manifest.json");
        if (!mf.is_open()) return nullptr;

        // Simplified parsing for demonstration
        std::string line;
        while (std::getline(mf, line)) {
            if (line.find("layer:") != std::string::npos) {
                manifest->layers.push_back(line.substr(line.find(":")+1));
            }
        }
        return manifest;
    }
};

int main(int argc, char* argv[]) {
    if (argc < 3) {
        std::cerr << "Usage: " << argv[0] << " <staging_dir> <upload_path>" << std::endl;
        return 1;
    }

    ContainerOrchestrator orchestrator(argv[1]);
    return orchestrator.process_upload(argv[2]);
}
